import { authenticator } from 'otplib';
import crypto from 'crypto';

// ── Legacy Base32 decoder (for secrets generated by the old custom encoder) ───

const BASE32_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

function base32Decode(input: string): Buffer {
  const cleanInput = input.toUpperCase().replace(/=+$/, '').replace(/[^A-Z2-7]/g, '');
  let bits = 0;
  let value = 0;
  const bytes: number[] = [];

  for (let i = 0; i < cleanInput.length; i++) {
    const index = BASE32_CHARS.indexOf(cleanInput[i]);
    if (index === -1) continue;

    value = (value << 5) | index;
    bits += 5;

    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 255);
      bits -= 8;
    }
  }

  return Buffer.from(bytes);
}

function legacyGenerateCode(secret: string, timeStep: number): string {
  const key = base32Decode(secret);
  const timeBuffer = Buffer.alloc(8);
  timeBuffer.writeUInt32BE(0, 0);
  timeBuffer.writeUInt32BE(timeStep, 4);

  const hmac = crypto.createHmac('sha1', key);
  hmac.update(timeBuffer);
  const digest = hmac.digest();

  const offset = digest[digest.length - 1] & 0xf;
  const binary =
    ((digest[offset] & 0x7f) << 24) |
    ((digest[offset + 1] & 0xff) << 16) |
    ((digest[offset + 2] & 0xff) << 8) |
    (digest[offset + 3] & 0xff);

  const otp = (binary % 1000000).toString();
  return otp.padStart(6, '0');
}

function legacyVerifyCode(secret: string, code: string, window: number = 1): boolean {
  const currentStep = Math.floor(Date.now() / 1000 / 30);
  const cleanCode = code.trim();

  for (let i = -window; i <= window; i++) {
    const generated = legacyGenerateCode(secret, currentStep + i);
    if (crypto.timingSafeEqual(Buffer.from(generated), Buffer.from(cleanCode))) {
      return true;
    }
  }

  return false;
}

// ── TOTP Service ──────────────────────────────────────────────────────────────

export class TotpService {
  constructor() {
    authenticator.options = { window: 1 };
  }

  /**
   * Generates a random Base32 secret key (using otplib standard)
   */
  generateSecret(): string {
    return authenticator.generateSecret();
  }

  /**
   * Generates standard OTPAuth URI for QR code generation
   */
  generateOtpAuthUrl(email: string, secret: string, issuer: string = 'AegisDB'): string {
    return authenticator.keyuri(email, issuer, secret);
  }

  /**
   * Generates 6-digit TOTP code for a secret
   */
  generateCode(secret: string): string {
    return authenticator.generate(secret);
  }

  /**
   * Verifies 6-digit TOTP code against secret.
   * Tries otplib first, then falls back to legacy HMAC-based verification
   * for backwards compatibility with secrets from the old custom encoder.
   */
  verifyCode(secret: string, code: string): boolean {
    if (!secret || !code || code.trim().length !== 6) return false;

    const cleanCode = code.trim();

    // Try standard otplib verification first
    try {
      if (authenticator.verify({ token: cleanCode, secret })) {
        return true;
      }
    } catch (err) {
      // otplib may throw on malformed secrets; fall through to legacy
    }

    // Fallback: legacy HMAC-based TOTP (for old custom-encoded secrets)
    try {
      return legacyVerifyCode(secret, cleanCode);
    } catch (err) {
      return false;
    }
  }
}

export const totpService = new TotpService();

